    "html_source": "<html>
<head>
<title>Secret TeaRoom by MitsukiLee｜サンプル動画</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Zen+Old+Mincho:wght@400;500;600&family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap');
html,body{overflow-x:hidden;margin:0;padding:0;}
body{background-color:#0c0906;}
.tr-wrap{max-width:920px;margin:0 auto;padding:0 24px;}
.tr-wrap,.tr-wrap *{box-sizing:border-box;}
.tr-section{padding:60px 0;}
.tr-eyebrow{font-family:'Cormorant Garamond',serif;font-weight:600;text-transform:uppercase;letter-spacing:.26em;color:#E29470;font-size:14px;text-align:center;margin:0 0 14px;}
.tr-rule{width:36px;height:1px;background:#A65F43;margin:0 auto;}
.tr-grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:2px;}
@media(max-width:640px){.tr-grid2{grid-template-columns:1fr;}}
.tr-card h3{font-family:'Cormorant Garamond',serif;font-weight:500;text-transform:uppercase;letter-spacing:.1em;color:#F3EADB;font-size:20px;margin:0 0 8px;text-align:center;}
.tr-card p{font-family:'Zen Old Mincho',serif;color:#EDE3D2;font-size:14px;text-align:center;margin:0;overflow-wrap:break-word;word-break:keep-all;}
.tr-band-sm{background:rgba(6,4,3,.84);padding:16px 14px;}
.tr-card-trigger{cursor:pointer;position:relative;}
@keyframes trPulse{0%{box-shadow:0 0 0 0 rgba(166,95,67,.55);}70%{box-shadow:0 0 0 16px rgba(166,95,67,0);}100%{box-shadow:0 0 0 0 rgba(166,95,67,0);}}
.tr-play-inline{width:60px;height:60px;border-radius:50%;background:#A65F43;border:2px solid #F5EEE1;display:flex;align-items:center;justify-content:center;margin:18px auto 0;animation:trPulse 2.2s infinite;}
.tr-play-inline::after{content:'';border-style:solid;border-width:12px 0 12px 19px;border-color:transparent transparent transparent #F5EEE1;margin-left:5px;}
.tr-card-trigger:hover .tr-play-inline{animation-play-state:paused;transform:scale(1.08);}
.tr-play-label{font-family:'Cormorant Garamond',serif;font-size:12.5px;letter-spacing:.14em;text-transform:uppercase;color:#E29470;font-weight:600;text-align:center;margin:10px 0 0;overflow-wrap:break-word;word-break:keep-all;}
.tr-modal{display:none;position:fixed;inset:0;background:rgba(4,3,2,.92);z-index:9999;align-items:center;justify-content:center;padding:24px;}
.tr-modal.open{display:flex;}
.tr-modal-inner{max-width:640px;width:100%;background:#0c0906;border:1px solid rgba(237,227,210,.18);padding:20px;position:relative;}
.tr-modal-close{position:absolute;top:-38px;right:0;background:none;border:none;color:#F3EADB;font-family:'Cormorant Garamond',serif;font-size:30px;line-height:1;cursor:pointer;padding:6px 10px;}
.tr-modal-title{font-family:'Cormorant Garamond',serif;font-weight:600;text-transform:uppercase;letter-spacing:.14em;color:#E29470;font-size:14px;text-align:center;margin:0 0 14px;}
#trModalVideo{width:100%;display:none;background:#000;border:0;}
.tr-modal-soon{display:none;text-align:center;color:#EDE3D2;font-family:'Zen Old Mincho',serif;font-size:14px;padding:60px 10px;}
</style>
</head>
<body>
<div class="tr-wrap">
<div class="tr-section" style="padding-top:50px;">
<p class="tr-eyebrow">What Happens Inside</p>
<div class="tr-rule" style="margin-bottom:20px;"></div>
<div class="tr-grid2">
<div class="tr-band-sm tr-card tr-card-trigger" data-video="https://utage-system.com/video/KKeh0YFGeqUl" data-title="Diet"><h3>Diet</h3><p>食べ方の知識を、日々の食卓へ</p><span class="tr-play-inline"></span><p class="tr-play-label">タップで動画を再生</p></div>
<div class="tr-band-sm tr-card tr-card-trigger" data-video="https://utage-system.com/video/FGbIAyVBsOLg" data-title="Modeling Method"><h3>Modeling Method</h3><p>モデルとしての所作とキャリアを学ぶ</p><span class="tr-play-inline"></span><p class="tr-play-label">タップで動画を再生</p></div>
<div class="tr-band-sm tr-card"><h3>Live</h3><p>Mitsukiがその月に学んだ最新の情報なども学べる時間</p></div>
<div class="tr-band-sm tr-card"><h3>Practice</h3><p>知識を実際の生活に落とし込む</p></div>
</div>
</div>
</div>
<div class="tr-modal" id="trVideoModal"><div class="tr-modal-inner"><button class="tr-modal-close" id="trModalClose">×</button><p class="tr-modal-title" id="trModalTitle"></p><iframe id="trModalVideo" allow="autoplay; fullscreen; encrypted-media" allowfullscreen style="aspect-ratio:16/9;"></iframe><div class="tr-modal-soon" id="trModalSoon">動画は準備中です。近日公開予定です。</div></div></div>
<script>
document.addEventListener('DOMContentLoaded', function(){
  var modal = document.getElementById('trVideoModal');
  if(!modal) return;
  var video = document.getElementById('trModalVideo');
  var title = document.getElementById('trModalTitle');
  var soon = document.getElementById('trModalSoon');
  var closeBtn = document.getElementById('trModalClose');
  function openModal(card){
    var src = card.getAttribute('data-video') || '';
    var t = card.getAttribute('data-title') || '';
    title.textContent = t;
    if(src){
      video.src = src;
      video.style.display = 'block';
      soon.style.display = 'none';
    } else {
      video.src = '';
      video.style.display = 'none';
      soon.style.display = 'block';
    }
    modal.classList.add('open');
    document.body.style.overflow = 'hidden';
  }
  function closeModal(){
    modal.classList.remove('open');
    video.src = '';
    document.body.style.overflow = '';
  }
  document.querySelectorAll('.tr-card-trigger').forEach(function(card){
    card.addEventListener('click', function(){ openModal(card); });
  });
  closeBtn.addEventListener('click', closeModal);
  modal.addEventListener('click', function(e){ if(e.target === modal) closeModal(); });
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape') closeModal(); });
});
</script>
</body>
</html>",
